sp_widget.client_script:
api.controller = function($scope,$rootScope,spUtil) {
	var c = this;


	$rootScope.$on('CaseId', function(event, sysId) {

		$scope.receivedSysId = sysId;
//console.log($scope.receivedSysId)
		c.server.get({'action':'getAuditRecord','value' : $scope.receivedSysId}).then(function(res){
			//console.log(res.data.caseAudit)
			$scope.activityLogs = res.data.caseAudit;
		})

		$scope.DownloadPDF=function(){

	c.server.get({'action':'create','value' : $scope.receivedSysId}).then(function(res){
			console.log(res.data.recordId)
		})
}
	});


};

sp_widget.css:
.activity-container {
  margin: 20px auto;
  width: 100%; /* Full width */
  max-width: 100%; /* Ensure it takes full screen width */
  overflow: hidden;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
  background-color: #ffffff;
}

.activity-table {
  width: 100%;
  border-collapse: collapse;
}

.activity-table thead {
  background-color: #f4f4f4;
}

.activity-table thead th {
  text-align: left;
  padding: 10px 15px;
  font-size: 14px;
  font-weight: bold;
  color: #333;
  border-bottom: 1px solid #ddd;
}

.activity-table tbody td {
  padding: 10px 15px;
  font-size: 14px;
  color: #333;
  border-bottom: 1px solid #ddd;
}

.activity-table tbody tr:last-child td {
  border-bottom: none;
}

/* Ensure activity takes up 40% and date takes 60% */
.activity-column {
  width: 40%; /* Activity takes 40% */
}

.date-column {
  width: 40%; /* Date takes 60% */
}

.widget-title {
  font-family: 'Arial', sans-serif;
  font-size: 24px;
  font-weight: bold;
  color: #03428E;
  background-color: #f9f9f9;
  padding: 20px;
  border-radius: 10px;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
  display: flex;
  align-items: center;
  justify-content: space-between;
  transition: background-color 0.3s ease;
  margin-bottom : 2rem;
}

.widget-title:hover {
  background-color: #e9e9e9;
}

.widget-title i {
  font-size: 24px;
  cursor: pointer;
}

.widget-title .exit-icon {
  margin-right: 10px;
}

.widget-title .content {
  flex-grow: 1; /* This ensures the content takes up available space */
  display: flex;
  justify-content: left; /* Centers the heading */
}

.widget-title .chart-icon {
  margin-left: 10px;
}


/* Button container styling */
.button-container {
  text-align: right;
  margin-top: 15px;
}

.search-button {
  background-color: #003366; /* Navy blue button */
  color: #fff;
  border: none;
  padding: 10px 20px;
  font-size: 16px;
  font-weight: bold;
  border-radius: 5px;
  cursor: pointer;
}

.search-button:hover {
  background-color: #002244; /* Darker navy blue on hover */
}

sp_widget.script:
(function() {

if (input && input.action == 'getAuditRecord') {

    var auditLogs = [];

    var caseSysId = new GlideRecord('x_rptp_kotak_kotak_audit_trail');
    caseSysId.addQuery('case_id', input.value);
   // caseSysId.orderBy('sys_created_on');
    caseSysId.query();

    while (caseSysId.next()) {
        var AuditObject = {
            activity: caseSysId.getValue('activity'),
            date: caseSysId.getValue('sys_created_on'),
						user: caseSysId.getValue("sys_created_by")
        };

        auditLogs.push(AuditObject);
    }


    data.caseAudit = auditLogs;
}
		if (input && input.action == 'create') {
	    var caseSysId1 = new GlideRecord('x_rptp_kotak_kotak_audit_trail');

	caseSysId1.initialize(); 

    if (input && input.value) {
        caseSysId1.setValue('activity', 'Audit Trail of the Case was sent via Email');
        caseSysId1.setValue('case_id', input.value);

         data.recordId = caseSysId1.insert();
			gs.addInfoMessage("Audit Trail pdf has been sent to your Email");

		}
	}

})();
